def normaliser_vente(ligne):
    for nom in ("sale_id", "shop_id", "product_id"):
        if not isinstance(ligne[nom], str):
            raise ValueError(f"Identifiant texte non nul attendu : {nom}")
    vente = {nom: ligne[nom].strip().upper()
             for nom in ("sale_id", "shop_id", "product_id")}
    if not all(vente.values()):
        raise ValueError("identifiant vide")
    vente["date"] = date_iso(ligne["date"])
    vente["quantity"] = entier_positif(ligne["quantity"])
    vente["unit_price_millimes"] = millimes(ligne["unit_price_tnd"])
    vente["amount_millimes"] = (
        vente["quantity"] * vente["unit_price_millimes"]
    )
    return vente

def lire_increment_sql(chemin_source, batch_id="2026-01-08"):
    conn = connexion_source(chemin_source)
    try:
        ventes = [dict(row) for row in
                  conn.execute(SQL_VENTES, (batch_id,))]
        changements = [dict(row) for row in
                       conn.execute(SQL_CHANGEMENTS, (batch_id,))]
    finally:
        conn.close()
    return ventes, changements, preuve_source(chemin_source, batch_id)

def trouver_shop_key(conn, shop_id, sale_date):
    versions = conn.execute(
        SQL_VERSION, (shop_id, sale_date, sale_date)
    ).fetchall()
    if len(versions) != 1:
        raise ValueError(
            f"Version temporelle unique attendue : {shop_id} au {sale_date}"
        )
    return versions[0][0]
